import java.util.*;

class Solution {
  public int minimumVisitedCells(int[][] g) {
    int m = g.length, n = g[0].length;
    TreeSet<Integer>[] rs = new TreeSet[m], cs = new TreeSet[n];
    for (int i = 0; i < m; i++) {
      rs[i] = new TreeSet<>();
      for (int j = 0; j < n; j++) rs[i].add(j);
    }
    for (int j = 0; j < n; j++) {
      cs[j] = new TreeSet<>();
      for (int i = 0; i < m; i++) cs[j].add(i);
    }
    int[][] d = new int[m][n];
    for (int[] x : d) Arrays.fill(x, -1);
    ArrayDeque<int[]> q = new ArrayDeque<>();
    d[0][0] = 1;
    q.add(new int[] {0, 0});
    rs[0].remove(0);
    cs[0].remove(0);
    while (!q.isEmpty()) {
      int[] z = q.remove();
      int i = z[0], j = z[1];
      for (Integer y = rs[i].ceiling(j + 1); y != null && y <= j + g[i][j]; ) {
        if (d[i][y] != -1 && d[i][y] <= d[i][j] + 1) break;
        rs[i].remove(y);
        cs[y].remove(i);
        d[i][y] = d[i][j] + 1;
        q.add(new int[] {i, y});
        y = rs[i].ceiling(y);
      }
      for (Integer x = cs[j].ceiling(i + 1); x != null && x <= i + g[i][j]; ) {
        if (d[x][j] != -1 && d[x][j] <= d[i][j] + 1) break;
        cs[j].remove(x);
        rs[x].remove(j);
        d[x][j] = d[i][j] + 1;
        q.add(new int[] {x, j});
        x = cs[j].ceiling(x);
      }
    }
    return d[m - 1][n - 1];
  }
}
